#include <bits/stdc++.h>
using namespace std;

int pos(const std::vector<char>& s, int a, int b, int c, int k) {
    int ret = 0;
    for (char x : s) {
        if (x == 'V') {
            if (a == 0) {
                if (k == 0) return ret;
                ret++;
            } else {
                a--;
            }
        } else if (x == 'K') {
            if (b == 0) {
                if (k == 1) return ret;
                ret++;
            } else {
                b--;
            }
        } else {
            if (c == 0) {
                if (k == 2) return ret;
                ret++;
            } else {
                c--;
            }
        }
    }
    return -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string line;
    cin >> line;
    vector<char> s(line.begin(), line.end());

    int nv = 0, nk = 0, ne = 0;
    for (char c : s) {
        if (c == 'V') nv++;
        else if (c == 'K') nk++;
        else ne++;
    }

    const int INF = 99999999;
    int dp[3][n+1][n+1][n+1];
    for (int a = 0; a < 3; a++)
        for (int i = 0; i <= n; i++)
            for (int j = 0; j <= n; j++)
                for (int k = 0; k <= n; k++)
                    dp[a][i][j][k] = INF;

    dp[2][0][0][0] = 0;

    int poss[3][nv+1][nk+1][ne+1];
    for (int i = 0; i <= nv; i++)
        for (int j = 0; j <= nk; j++)
            for (int k = 0; k <= ne; k++)
                for (int l = 0; l < 3; l++)
                    poss[l][i][j][k] = pos(s, i, j, k, l);

    for (int i = 0; i <= nv; i++) {
        for (int j = 0; j <= nk; j++) {
            for (int k = 0; k <= ne; k++) {
                for (int l = 0; l < 3; l++) {
                    int current = dp[l][i][j][k];
                    if (current == INF) continue;
                    if (i + 1 <= nv && poss[0][i][j][k] != -1) {
                        int v = poss[0][i][j][k];
                        dp[0][i + 1][j][k] = std::min(dp[0][i + 1][j][k], current + v);
                        dp[1][i + 1][j][k] = std::min(dp[1][i + 1][j][k], current + v);
                        dp[2][i + 1][j][k] = std::min(dp[2][i + 1][j][k], current + v);
                    }
                    if (j + 1 <= nk && poss[1][i][j][k] != -1) {
                        int v = poss[1][i][j][k];
                        dp[1][i][j + 1][k] = std::min(dp[1][i][j + 1][k], current + v);
                        dp[2][i][j + 1][k] = std::min(dp[2][i][j + 1][k], current + v);
                    }
                    if (k + 1 <= ne && poss[2][i][j][k] != -1) {
                        int v = poss[2][i][j][k];
                        dp[2][i][j][k + 1] = std::min(dp[2][i][j][k + 1], current + v);
                        dp[1][i][j][k + 1] = std::min(dp[1][i][j][k + 1], current + v);
                        dp[0][i][j][k + 1] = std::min(dp[0][i][j][k + 1], current + v);
                    }
                }
            }
        }
    }

    int answer = std::min({dp[0][nv][nk][ne], dp[1][nv][nk][ne], dp[2][nv][nk][ne]});
    cout << answer << "\n";

    return 0;
}

